class Solution {
  public long minOperationsToMakeMedianK(int[] nums, int k) {
    int[] sorted = nums.clone();
    Arrays.sort(sorted);
    int n = sorted.length, median = n / 2;
    long operations = 0;
    if (sorted[median] < k) {
      for (int i = median; i < n && sorted[i] < k; i++) operations += k - sorted[i];
    } else {
      for (int i = median; i >= 0 && sorted[i] > k; i--) operations += sorted[i] - k;
    }
    return operations;
  }
}
